CREATE OR REPLACE FUNCTION public.user_modules(_uid uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (CASE WHEN _uid IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid) THEN ARRAY[]::text[] WHEN public.has_role(_uid,'master') THEN ARRAY['agenda','historicos','oficina','os'] WHEN public.has_role(_uid,'oficina') THEN ARRAY['oficina'] ELSE ARRAY['agenda','historicos','os'] END) || CASE WHEN public.can_view_vehicles(_uid) THEN ARRAY['veiculos'] ELSE ARRAY[]::text[] END $$;